import{_ as t,C as i,o as n,c as o,aj as r,G as s,j as l}from"./chunks/framework.BwH0p-pt.js";const g="/assets/1.0/images/magic-ai/image-generation.png",p="/assets/1.0/images/magic-ai/translation.png",b=JSON.parse('{"title":"Magic AI","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/magic/magic-ai.md","filePath":"1.0/magic/magic-ai.md","lastUpdated":1781079046000}'),m={name:"1.0/magic/magic-ai.md"};function c(u,e,d,h,f,I){const a=i("ImagePopup");return n(),o("div",null,[e[0]||(e[0]=r('<h1 id="magic-ai" tabindex="-1">Magic AI <a class="header-anchor" href="#magic-ai" aria-label="Permalink to &quot;Magic AI&quot;">​</a></h1><p>Magic AI is an intelligent feature in <strong>UnoPim</strong> that helps you create content faster using Artificial Intelligence. It supports <strong>content generation</strong>, <strong>image generation</strong>, <strong>translation</strong>, and <strong>system prompt management</strong> from one simple configuration panel.</p><p>It is built for teams who want quick, high-quality results without technical complexity.</p><h2 id="general-settings" tabindex="-1">General Settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General Settings&quot;">​</a></h2><p>Use General Settings to connect Magic AI with your preferred AI provider.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><ul><li><strong>Enable / Disable</strong>: Turn Magic AI on or off</li><li><strong>AI Platform</strong>: Choose the AI provider</li><li><strong>API Key</strong>: Enter your API key</li><li><strong>Organization (Optional)</strong>: Required for some providers</li><li><strong>LLM API Domain</strong>: Use for custom or self-hosted APIs</li><li><strong>System Prompt</strong>: Configure the AI prompt behavior to define how the AI should respond.</li><li><strong>Max Tokens</strong>: Set the maximum number of tokens for AI responses to control output length and costs.</li></ul><p>After setup, Magic AI is available across supported features in UnoPim.</p><h2 id="content-generation" tabindex="-1">Content Generation <a class="header-anchor" href="#content-generation" aria-label="Permalink to &quot;Content Generation&quot;">​</a></h2><p>Magic AI generates high-quality <strong>Product</strong> and <strong>Category</strong> content using Large Language Models (LLMs).</p><h3 id="supported-ai-providers" tabindex="-1">Supported AI Providers <a class="header-anchor" href="#supported-ai-providers" aria-label="Permalink to &quot;Supported AI Providers&quot;">​</a></h3><p><strong>OpenAI</strong></p><ul><li>Text &amp; Multimodal: gpt-5.2, gpt-5, gpt-5.1, gpt-5-mini, gpt-5-nano, gpt-4o, gpt-4o-mini, gpt-3.5-turbo</li><li>Image Generation: gpt-image-1.5, gpt-image-1, gpt-image-1-mini, dall-e-2, dall-e-3</li></ul><p><strong>Ollama</strong></p><ul><li>llama2, llama3, mistral, qwen</li><li>deepseek-coder, phi, llava</li></ul><p><strong>Gemini</strong></p><ul><li>Text &amp; Multimodal: gemini-2.5-pro, gemini-2.5-flash, gemini-2.0-flash, gemini-1.5-flash-latest, gemini-1.5-pro</li><li>Image Generation: gemini-2.5-flash-image, gemini-3-pro-image-preview</li></ul><p><strong>Groq (xAI)</strong></p><ul><li>deepseek-r1-distill-llama-70b</li><li>llama-3.1-8b-instant</li><li>openai/gpt-oss-120b, openai/gpt-oss-20b</li><li>groq/compound, qwen/qwen3-32b, moonshotai/kimi-k2-instruct-0905</li></ul><p><strong>Magic AI</strong> helps create consistent, SEO-friendly content faster and more efficiently.</p><h2 id="image-generation" tabindex="-1">Image Generation <a class="header-anchor" href="#image-generation" aria-label="Permalink to &quot;Image Generation&quot;">​</a></h2><p>Enable Image Generation to create images during upload using AI models like DALL·E.</p><p><img src="'+g+'" alt="&#39;image-generation&#39;"></p><h2 id="translation-product-values-translation" tabindex="-1">Translation &amp; Product Values Translation <a class="header-anchor" href="#translation-product-values-translation" aria-label="Permalink to &quot;Translation &amp; Product Values Translation&quot;">​</a></h2><p>Magic AI helps translate product and category content into multiple languages.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Enable Translation</li><li>Select Translation Model</li><li>Replace existing values (optional)</li><li>Choose Source &amp; Target Channels</li><li>Select Source &amp; Target Locales</li></ul><p>This keeps your catalog consistent across regions.</p><p><img src="'+p+'" alt="Translation"></p><hr><p>Magic AI makes UnoPim smarter and faster for managing product content.</p><hr>',32)),s(a,{src:"/assets/1.0/images/magic-ai/content.png",alt:"Magic Content"}),e[1]||(e[1]=l("p",null,"Say goodbye to time-consuming manual content creation as Magic AI crafts compelling and unique descriptions, saving you valuable time and effort.",-1))])}const P=t(m,[["render",c]]);export{b as __pageData,P as default};
